head.script:
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gDate;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gDepCd;
scwin.gRowCnt;
scwin.gStat;
scwin.gSrhCnt;

// 교체요구 대상자 관리

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.search();

        // 조건검색에 교체요구일
        panel_2.hide();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "ACPT_NO") {
            if (scwin.gAcptNo !== "" && scwin.gAcptNo.length > 0) {
                await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
            } else {
                await $c.win.alert("공시뷰어를 볼 수 없습니다");
            }
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnPopup
 * @description grd Grid On Popup 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnPopup = async function(row, colid, data) {
    try {
        const options = {
            id: "ULDCOM00007_POP",
            title: "회사검색",
            type: "browserPopup",
            width: "10px",
            height: "20px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/common/ULDCOM00007_POP.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.grd_Grid_OnPopup" });
    }
};

/**
 * @method
 * @name dts_RepcReqPrn_OnLoadError
 * @description dts_RepcReqPrn 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_RepcReqPrn_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_RepcReqPrn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.dts_RepcReqPrn_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_RepcReqPrn_OnLoadCompleted
 * @description dts_RepcReqPrn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_RepcReqPrn_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        scwin.gSrhCnt = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35116.dts_RepcReqPrn_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35116.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF35116.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "교체요구대상자관리", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35116.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
