 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35116.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35116.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35116.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35116.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Save1_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save1_onclick = async function() {
    try {
        // 저장은 해당행의 현재종목담당자만 할 수 있음 20160219
        // 회사코드를 가져와서 종목에 있는지 확인해야함

        scwin.gRowCnt = 0;
        let gStatCnt = 0;
        let gIsurCdStr = "";
        for (let k = 1; k <= dts_RepcReqPrn.getRowCount(); k++) {
            scwin.gStat = dts_RepcReqPrn.getRowStatus(k);
            if (scwin.gStat === '1' || scwin.gStat === '3') {
                gStatCnt++;
                gIsurCdStr = dts_RepcReqPrn.getCellData(k, "ISUR_CD");
                for (let j = 1; j <= dts_bycorpChrg.getRowCount(); j++) {
                    if (gIsurCdStr === dts_bycorpChrg.getCellData(j, "ISUR_CD")) {
                        scwin.gRowCnt++;
                        break;
                    }
                }
            }
        }
        if (scwin.gSrhCnt === dts_RepcReqPrn.getRowCount() && gStatCnt <= 0) {
            await $c.win.alert("변경된 사항이 없습니다.");
        } else {
            if (gStatCnt === scwin.gRowCnt) {
                scwin.save();
            } else {
                await $c.win.alert("해당 회사의 종목담당자만 입력 또는 수정이 가능합니다.");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.btn_Save1_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
