};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 저장 되었습니다.");
        scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.trs_save_OnSuccess" });
    }
};

/**
 * @method
