 */
scwin.trs_save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name btn_AddRow_onclick
 * @description 「행추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_AddRow_onclick = async function() {
    try {
        // 행삽입은 (코)공시1팀~3팀 만 할 수 있다.  20160219
        // 코_공시4팀 추가 2018.04.09
        // 코_T1,T2팀 추가 2020.03.20
        // 3495 추가 2021.03.12
        if (scwin.gDepCd === '3420' || scwin.gDepCd === '3430' || scwin.gDepCd === '3440' || scwin.gDepCd === '3460' || scwin.gDepCd === '3490' || scwin.gDepCd === '3495' || scwin.gDepCd === '3470' || scwin.gDepCd === '3480') {
            if (dts_RepcReqPrn.getRowCount() <= 0) {
                dts_RepcReqPrn.insertRow();
            } else {
                dts_RepcReqPrn.insertRow(dts_RepcReqPrn.getRowPosition() - 1);
            }
        } else {
            await $c.win.alert("행삽입 권한이 없습니다.");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.btn_AddRow_onclick" });
    }
};

/**
 * @method
 * @name btn_DelRow_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_DelRow_onclick = async function() {
    try {
        scwin.gAcptNo = dts_RepcReqPrn.getCellData(dts_RepcReqPrn.getRowPosition(), "ACPT_NO");
        scwin.gIsurCd = dts_RepcReqPrn.getCellData(dts_RepcReqPrn.getRowPosition(), "ISUR_CD");
        // alert("gAcptNo : " + gAcptNo);
        const gLstChgEmpNo = dts_RepcReqPrn.getCellData(dts_RepcReqPrn.getRowPosition(), "LST_CHG_EMP_NO");
        if (scwin.gAcptNo !== '' && scwin.gAcptNo.length > 0) {
            // 행삭제는 공시로 추출된 내용은 삭제불가, 20160219
            await $c.win.alert("불성시법인 지정 공시로 추출된 행은 삭제 할 수 없습니다.");
        } else {
            // 행삽입으로 생성된 행에 대해서는 입력한 사람만 삭제가능 20160219
            if (gLstChgEmpNo !== '' && gLstChgEmpNo.length > 0) {
                if (gLstChgEmpNo === scwin.gEmpNo) {
                    dts_RepcReqPrn.removeRow(dts_RepcReqPrn.getRowPosition());
                } else {
                    await $c.win.alert("해당 행을 입력한 사용자가 아니므로 행삭제를 할 수 없습니다.");
                }
                /*else{
                    //종목담당자도 삭제 가능
                	gRowCnt = 0;
                	for (var j = 1; j <= dts_bycorpChrg.CountRow; j++) {
                		if(gIsurCd == dts_bycorpChrg.NameString(j,"ISUR_CD")){
                			gRowCnt ++;
                			break;
                		}
                	}
                	if(gRowCnt > 0 ){
                		dts_RepcReqPrn.DeleteRow(dts_RepcReqPrn.RowPosition);
                	}
                	else{
                		alert("해당 행을 입력한 사용자가 아니거나 해당 회사의 종목담당자가 아니므로 행삭제를 할 수 없습니다.");
                	}
                }*/
            }
            // 저장전 행삽입한 것을 삭제할때
            else {
                dts_RepcReqPrn.removeRow(dts_RepcReqPrn.getRowPosition());
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35116.btn_DelRow_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
                 * @method
                 * @name setCode
                 * @description set Code 처리
                 * @returns {Promise<void>}
                 * @hidden N
                 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '6') {
        // grd_Grid.ColumnProp("MKT_NM", "Show") = false;
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        panel_mkt.hide();
    } else {
        rdo_MKT_ID.setValue("2");
    }

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    /* 03906 : DISCLS_PRN_REPC_RSN_CD : 공시대상자교체사유코드	*/
    const sbmOptions = {
        id : "sbm_dts_RepcRsnCd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_RepcRsnCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let url_list = "/PenaltyImposition.do?method=listRepcReqPrnIsurCd&inputMessageId=REPCREQPRN_CHECK_INOUT" + "&outputMessageId=REPCREQPRN_CHECK_INOUT";

    // 디폴트 전체로해서 조회함.
    let url_cond = "&EMP_NO=" + scwin.gEmpNo;
    dts_bycorpChrg.DataID = encodeURI(url_list + url_cond);
    dts_bycorpChrg.reset();
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let url_list = "/PenaltyImposition.do?method=listRepcReqPrn&inputMessageId=REPCREQPRN_INOUT" + "&outputMessageId=REPCREQPRN_INOUT";

    // 디폴트 전체로해서 조회함.
    let url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + "&TO_DATE=" + "&LD_MKT_TP_CD=" + rdo_MKT_ID.getValue() + "&OBJ_NM=" + cmb_objnm.getValue() + "&SCREN_ID=" + 'ULDSTF35116.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_RepcReqPrn.DataID = encodeURI(url_list + url_cond);
    dts_RepcReqPrn.reset();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_RepcReqPrn.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_RepcReqPrn.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {void}
 * @hidden N
 */
scwin.save = function() {
    let gCnt = 0;
    dts_RepcReqPrn.setBroadcast(false);
    for (let k = 1; k <= dts_RepcReqPrn.getRowCount(); k++) {
        scwin.gStat = dts_RepcReqPrn.getRowStatus(k);
        if (scwin.gStat === TB_JOB_INSERT) {
            gCnt++;
            dts_RepcReqPrn.setCellData(k, "SEQ", gCnt);
        }
    }
    dts_RepcReqPrn.setBroadcast(true, true);
    grd_Grid.Redraw = true;
    if (window.confirm("저장하시겠습니까?")) {
        const url = "/PenaltyImposition.do?method=saveRepcReqPrn&EMP_NO=" + scwin.gEmpNo + "&SCREN_ID=" + 'ULDSTF35116.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_RepcReqPrn)";
        trs_save.Post();
    }
};

/**
 * @method
 * @name grd_Grid_CanColumnPosChange
 * @description grd Grid Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
